const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict'),pw=require('playwright');let browser,server;const engine=process.argv[2]||'chromium',root=process.cwd();
(async()=>{server=http.createServer((req,res)=>{let f=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname);if(fs.existsSync(f)&&fs.statSync(f).isDirectory())f=path.join(f,'index.html');if(!f.startsWith(root+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile())return res.writeHead(404).end();res.setHeader('Content-Type',({'.js':'application/javascript','.css':'text/css','.html':'text/html','.svg':'image/svg+xml'})[path.extname(f)]||'application/octet-stream');res.end(fs.readFileSync(f));});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;browser=await pw[engine].launch(process.env.STUDENTS_BROWSER_EXECUTABLE?{executablePath:process.env.STUDENTS_BROWSER_EXECUTABLE}:{});const ctx=await browser.newContext({viewport:{width:1440,height:1000},serviceWorkers:'block'}),p=await ctx.newPage(),errors=[];p.on('pageerror',e=>errors.push(e.message));await ctx.route('**/*',r=>new URL(r.request().url()).origin===base?r.continue():r.abort());await p.goto(base+'/workspace.html');await p.waitForFunction(()=>window.MT_WORKSPACE_APP);const modules=await p.evaluate(()=>MT_INTERACTIVE_MODULES);let checks=0;for(const m of modules){await p.goto(base+'/students/'+m.url);await p.locator('#study-analysis > summary').waitFor();await p.locator('#study-analysis').evaluate(n=>n.open=true);await p.locator('#capture-a').waitFor();const detail=await p.evaluate(()=>{const c=MT_ANALYSIS_ADAPTER.capture(),z=MT_ANALYSIS_ADAPTER.evaluate(c.id,c.inputs),rank=MT_ANALYSIS.sensitivity(x=>MT_ANALYSIS_ADAPTER.evaluate(c.id,x),c.inputs,c.metrics[0].id),mismatches=c.metrics.filter(m=>Number.isFinite(m.value)&&(!Number.isFinite(z.results[m.id])||Math.abs(z.results[m.id]-m.value)>1e-8*Math.max(1,Math.abs(m.value))));return{mismatches,rank:rank.length,finite:rank.every(r=>r.error||Number.isFinite(r.slope)&&[null,undefined].includes(r.elasticity)||Number.isFinite(r.elasticity))};});assert.deepEqual(detail.mismatches,[],m.id+' displayed and analysis results match');assert.ok(detail.rank&&detail.finite);await p.locator('#capture-a').click();await p.locator('#capture-b').click();assert.ok(await p.locator('#analysis-comparison svg').count(),m.id+' common axes');assert.ok(!/NaN|Infinity/.test(await p.locator('#analysis-comparison').innerHTML()),m.id);checks+=4;console.log('ANALYSIS '+engine+'/'+m.id);}
await p.goto(base+'/students/advanced-lab.html#thermal-expansion');await p.locator('#study-analysis').evaluate(n=>n.open=true);await p.locator('#heat-run').waitFor();await p.locator('#analysis-metric').selectOption('Actual length change (mm)');await p.locator('#heat-x').selectOption('alpha');await p.locator('#heat-y').selectOption('delta');await p.locator('#heat-run').click();await p.locator('#heat-csv:not([disabled])').waitFor();assert.equal(await p.locator('#heat-result tbody tr').count(),400);await p.locator('#analysis-symbol').selectOption('alpha');await p.locator('#analysis-highlight').click();assert.equal(await p.locator('[name=alpha]').evaluate(n=>n===document.activeElement),true);assert.match(await p.locator('[data-analysis-annotation]').textContent(),/12/);assert.deepEqual(errors,[]);console.log(JSON.stringify({status:'PASS',engine,models:45,checks:checks+3,heatmapCells:400,scope:'Analysis matches every displayed baseline, finite local sensitivities, common-axis overlays, full two-input map and keyboard-linked input/diagram.'}));await ctx.close();})().catch(e=>{console.error(e);process.exitCode=1;}).finally(async()=>{await browser?.close();await new Promise(r=>server?server.close(r):r());});
